package com.example.domain.model.i18n

internal object DuaMr3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_rahmataka_arju" to DuaText("तुझ्या कृपेची आशा करतो", "हे अल्लाह! मी तुझ्या कृपेची आशा करतो, म्हणून मला डोळ्याच्या पापणीइतकाही माझ्या मनाच्या हवाली करू नकोस, आणि माझी सर्व कामे सुधार. तुझ्याशिवाय कोणी उपास्य नाही.", "संकटग्रस्ताची दुआ (दअवातुल मकरूब).", "नबी ﷺ यांनी हिला संकटग्रस्ताची दुआ म्हटले."),
        "dua_against_enemy_ahzab" to DuaText("शत्रूच्या सैन्याविरुद्ध", "हे अल्लाह, ग्रंथ उतरवणाऱ्या, लवकर हिशोब घेणाऱ्या! सैन्यांचा पराभव कर. हे अल्लाह! त्यांचा पराभव कर आणि त्यांना हादरवून टाक.", "शत्रूविरुद्ध — अहजाबच्या युद्धाची दुआ.", "शत्रूविरुद्ध नबी ﷺ यांची दुआ."),
        "dua_anta_adudi" to DuaText("तूच माझा आधार आहेस", "हे अल्लाह! तूच माझा बाहू आणि मदतगार आहेस. तुझ्याचद्वारे मी योजना करतो, तुझ्याचद्वारे चढाई करतो आणि तुझ्याचद्वारे लढतो.", "स्पर्धा किंवा मोठ्या आव्हानापूर्वी.", "नबी ﷺ युद्धाच्या वेळी हे म्हणत."),
        "dua_ikfinihim" to DuaText("त्यांच्याविरुद्ध मला पुरेसा हो", "हे अल्लाह! तुझ्या इच्छेनुसार त्यांच्याविरुद्ध माझ्यासाठी पुरेसा हो.", "अत्याचाऱ्यांच्या वाईटापासून — असहाबुल उखदूदच्या मुलाची दुआ.", "अल्लाहने त्या मुलाला अत्याचाऱ्यांपासून वाचवले."),
        "dua_qadarullah" to DuaText("काही वाईट घडल्यावर", "ही अल्लाहची नियती आहे, आणि त्याने जे इच्छिले ते केले.", "एखादी अप्रिय गोष्ट घडल्यास 'जर' म्हणण्याऐवजी.", "'जर' शैतानाचा दरवाजा उघडतो."),
        "dua_ala_kulli_hal" to DuaText("प्रत्येक स्थितीत स्तुती", "प्रत्येक स्थितीत सर्व स्तुती अल्लाहसाठी आहे.", "एखादी नावडती गोष्ट घडल्यास.", "नबी ﷺ नावडत्या गोष्टीवर हे म्हणत."),
        "dua_dogs_barking" to DuaText("रात्री कुत्र्यांचे भुंकणे ऐकून", "मी धिक्कारलेल्या शैतानापासून अल्लाहचा आश्रय मागतो.", "रात्री कुत्र्यांचे भुंकणे किंवा गाढवाचे ओरडणे ऐकून.", "ते अशा गोष्टी पाहतात ज्या तुम्ही पाहत नाही."),
        "dua_leaving_home_adilla" to DuaText("मार्गभ्रष्टतेपासून आश्रय", "हे अल्लाह! मी तुझा आश्रय मागतो की मी भरकटू नये किंवा भरकटवला जाऊ नये, घसरू नये किंवा घसरवला जाऊ नये, अन्याय करू नये किंवा माझ्यावर अन्याय होऊ नये, मूर्खपणा करू नये किंवा माझ्याशी मूर्खपणा होऊ नये.", "घरातून निघताना — उम्मे सलमा (र.) यांचे वर्णन.", "नबी ﷺ घरातून निघताना नेहमी हे पठण करत."),
        "dua_ascending_descending" to DuaText("चढताना आणि उतरताना", "अल्लाह सर्वात महान आहे (चढताना). — अल्लाह पवित्र आहे (उतरताना).", "प्रवासात चढताना 'अल्लाहु अकबर', उतरताना 'सुब्हानल्लाह'.", "प्रवासात सहाबा (र.) यांची प्रथा."),
        "dua_traveller_sahar" to DuaText("पहाटेपूर्वी प्रवाशाची दुआ", "ऐकणाऱ्याने अल्लाहची स्तुती आणि आमच्यावरील त्याच्या उत्तम कृपा (इतरांपर्यंत) पोहोचवल्या. हे आमच्या रब! आमचा सोबती हो आणि आमच्यावर कृपा कर — आगीपासून अल्लाहचा आश्रय मागत (हे म्हणतो).", "प्रवासात सहरीच्या वेळी.", "नबी ﷺ प्रवासात सहरीच्या वेळी हे म्हणत."),
        "dua_zawwadakallah" to DuaText("प्रवाशाला: अल्लाह तक्वाची शिदोरी देवो", "अल्लाह तुला तक्वाची शिदोरी देवो, तुझी पापे माफ करो आणि तू जिथे असशील तिथे तुझ्यासाठी भले सोपे करो.", "प्रवाशाला निरोप देताना.", "नबी ﷺ यांनी प्रवासाला जाणाऱ्याला ही दुआ दिली."),
        "dua_traveller_to_resident" to DuaText("प्रवाशाची कुटुंबासाठी दुआ", "मी तुम्हाला त्या अल्लाहच्या स्वाधीन करतो ज्याच्याकडे ठेवलेल्या ठेवी वाया जात नाहीत.", "प्रवासाला जाणारा कुटुंबाला निरोप देताना.", "कुटुंबाचे संरक्षण अल्लाहच्या स्वाधीन."),
        "dua_entering_village" to DuaText("गाव किंवा शहरात प्रवेश", "हे अल्लाह, सात आकाश आणि ज्यांवर त्यांची सावली आहे त्यांच्या रब, सात पृथ्वी आणि जे त्यांनी उचलले आहे त्यांच्या रब, शैतानांच्या आणि ज्यांना त्यांनी भरकटवले त्यांच्या रब, वाऱ्यांच्या आणि जे त्यांनी उडवले त्यांच्या रब! आम्ही तुझ्याकडे या वस्तीचे आणि तिच्या रहिवाशांचे भले मागतो, आणि तिच्या, तिच्या लोकांच्या आणि तिच्यात जे आहे त्याच्या वाईटापासून तुझा आश्रय मागतो.", "एखाद्या वस्ती/शहरात प्रवेश करण्यापूर्वी.", "नबी ﷺ ज्या वस्तीत प्रवेश करू इच्छित तेव्हा हे पठण करत."),
        "dua_vehicle_stumbles" to DuaText("वाहन घसरल्यास", "अल्लाहच्या नावाने.", "वाहन घसरल्यास किंवा ठेच लागल्यास 'शैतानाचा नाश होवो' म्हणण्याऐवजी.", "बिस्मिल्लाह म्हटल्याने शैतान माशीइतका लहान होतो."),
        "dua_ajz_kasal_haram" to DuaText("दुर्बलता आणि म्हातारपणापासून आश्रय", "हे अल्लाह! मी तुझा आश्रय मागतो दुर्बलता आणि आळसापासून, भ्याडपणा आणि म्हातारपणापासून, जीवन-मृत्यूच्या फितन्यापासून आणि कबरीच्या शिक्षेपासून.", "दैनंदिन आश्रयाची व्यापक दुआ.", "नबी ﷺ यांची वारंवार केलेली दुआ."),
        "dua_sharri_ma_amiltu" to DuaText("माझ्या कर्मांच्या वाईटापासून आश्रय", "हे अल्लाह! मी तुझा आश्रय मागतो जे कर्म मी केले त्याच्या वाईटापासून, आणि जे केले नाही त्याच्या वाईटापासून.", "आयशा (र.) यांच्या मते नबी ﷺ यांची दुआ.", "केलेल्या आणि न केलेल्या दोन्हींच्या परिणामापासून संरक्षण."),
        "dua_jahdil_bala" to DuaText("कठोर परीक्षेपासून आश्रय", "हे अल्लाह! मी तुझा आश्रय मागतो कठोर परीक्षेपासून, दुर्भाग्याच्या तावडीपासून, वाईट निर्णयापासून आणि शत्रूंच्या हसण्यापासून.", "कठोर परीक्षा आणि शत्रूंच्या आनंदापासून आश्रय.", "नबी ﷺ या चार गोष्टींपासून आश्रय मागत."),
        "dua_fitnat_ghina_faqr" to DuaText("श्रीमंती आणि गरिबीच्या फितन्यापासून आश्रय", "हे अल्लाह! मी तुझा आश्रय मागतो आळस आणि म्हातारपणापासून, पाप आणि कर्जापासून, कबरीच्या फितन्या आणि शिक्षेपासून, आगीच्या फितन्या आणि शिक्षेपासून, श्रीमंतीच्या फितन्याच्या वाईटापासून आणि गरिबीच्या फितन्यापासून.", "कबर, जहन्नम, श्रीमंती आणि गरिबीच्या फितन्यांपासून आश्रय (दुआचा भाग).", "नबी ﷺ यांची व्यापक आश्रयाची दुआ."),
        "dua_kufr_faqr" to DuaText("कुफ्र आणि दारिद्र्यापासून आश्रय", "हे अल्लाह! मी कुफ्र आणि दारिद्र्यापासून तुझा आश्रय मागतो, आणि कबरीच्या शिक्षेपासून तुझा आश्रय मागतो. तुझ्याशिवाय कोणी उपास्य नाही.", "सकाळ-संध्याकाळ तीन वेळा.", "अबू बकरा (र.) यांनी नबी ﷺ यांना हे पठण करताना ऐकले."),
        "dua_sharri_sami" to DuaText("माझ्या इंद्रियांच्या वाईटापासून आश्रय", "हे अल्लाह! मी तुझा आश्रय मागतो माझ्या कानांच्या वाईटापासून, माझ्या डोळ्यांच्या वाईटापासून, माझ्या जिभेच्या वाईटापासून, माझ्या हृदयाच्या वाईटापासून आणि माझ्या वासनेच्या वाईटापासून.", "शकल बिन हुमैद (र.) यांना शिकवली.", "अवयव आणि मनाला पापापासून वाचवण्याची दुआ."),
        "dua_hadm_gharaq" to DuaText("अचानक मृत्यू आणि अपघातांपासून आश्रय", "हे अल्लाह! मी तुझा आश्रय मागतो (इमारत) कोसळण्यापासून, उंचावरून पडण्यापासून, बुडणे, जळणे आणि म्हातारपणापासून, मृत्यूच्या वेळी शैतानाच्या भुलवण्यापासून, तुझ्या मार्गावरून पाठ फिरवून मरण्यापासून, आणि (विषारी प्राण्याच्या) दंशाने मरण्यापासून.", "अपघात आणि वाईट मृत्यूपासून आश्रय.", "नबी ﷺ यांची आश्रयाची दुआ."),
        "dua_ju_khiyanah" to DuaText("भूक आणि विश्वासघातापासून आश्रय", "हे अल्लाह! मी भुकेपासून तुझा आश्रय मागतो कारण ती वाईट सोबती आहे, आणि विश्वासघातापासून तुझा आश्रय मागतो कारण तो वाईट जिवलग आहे.", "भूक आणि विश्वासघातापासून आश्रय.", "नबी ﷺ यांची आश्रयाची दुआ."),
        "dua_huda_tuqa" to DuaText("मार्गदर्शन, तक्वा, पावित्र्य आणि निरपेक्षता", "हे अल्लाह! मी तुझ्याकडे मार्गदर्शन, तक्वा, चारित्र्याचे पावित्र्य आणि निरपेक्षता मागतो.", "नबी ﷺ यांची संक्षिप्त व्यापक दुआ.", "दीन आणि दुनियेच्या चार मूलभूत कृपा."),
        "dua_aslih_li_dini" to DuaText("माझा दीन, दुनिया आणि आखिरत सुधार", "हे अल्लाह! माझा दीन सुधार जो माझ्या प्रत्येक कामाचे संरक्षण आहे, माझी दुनिया सुधार ज्यात माझी उपजीविका आहे, माझी आखिरत सुधार जिथे मला परत जायचे आहे. जीवनाला माझ्यासाठी प्रत्येक भल्यात वाढ बनव, आणि मृत्यूला प्रत्येक वाईटापासून सुटका बनव.", "दीन, दुनिया आणि आखिरत — तिघांचे सुधारणे.", "नबी ﷺ यांची व्यापक दुआ."),
        "dua_musarrifal_qulub" to DuaText("आमची हृदये तुझ्या आज्ञापालनाकडे वळव", "हे अल्लाह, हृदये फिरवणाऱ्या! आमची हृदये तुझ्या आज्ञापालनाकडे वळव.", "हृदयाला आज्ञापालनावर स्थिर ठेवण्याची दुआ.", "सर्व माणसांची हृदये रहमानच्या दोन बोटांमध्ये आहेत."),
        "dua_jannah_nar" to DuaText("जन्नत मागणे, आगीपासून आश्रय", "हे अल्लाह! मी तुझ्याकडे जन्नत मागतो आणि आगीपासून तुझा आश्रय मागतो.", "तशह्हुदनंतर किंवा कधीही.", "नबी ﷺ म्हणाले: आम्हीही याच्याच भोवती दुआ करतो."),
        "dua_khayri_kullih" to DuaText("सर्व भले, आता आणि नंतर", "हे अल्लाह! मी तुझ्याकडे सर्व भले मागतो — लवकरचे आणि उशिराचे, जे मी जाणतो आणि जे जाणत नाही — आणि सर्व वाईटापासून तुझा आश्रय मागतो — लवकरचे आणि उशिराचे, जे मी जाणतो आणि जे जाणत नाही. हे अल्लाह! मी तुझ्याकडे जन्नत आणि त्याच्या जवळ नेणाऱ्या बोलणे व कर्माची याचना करतो, आणि आगीपासून आणि त्याच्या जवळ नेणाऱ्या बोलणे व कर्मापासून आश्रय मागतो.", "नबी ﷺ यांनी आयशा (र.) यांना ही व्यापक दुआ शिकवली (दुआचा भाग).", "प्रत्येक भले एकत्र करणारी दुआ."),
        "dua_ihdini_saddidni" to DuaText("मला मार्गदर्शन दे आणि सरळ ठेव", "हे अल्लाह! मला मार्गदर्शन दे आणि मला सरळ ठेव.", "नबी ﷺ यांनी अली (र.) यांना शिकवली.", "मार्गदर्शनाला रस्त्याच्या मार्गदर्शनाने आणि सरळपणाला बाणाच्या सरळपणाने आठवा."),
        "dua_hubbaka" to DuaText("अल्लाहचे प्रेम मागणे", "हे अल्लाह! मी तुझ्याकडे तुझे प्रेम मागतो, आणि जो तुझ्यावर प्रेम करतो त्याचे प्रेम, आणि असे कर्म जे मला तुझ्या प्रेमापर्यंत पोहोचवेल. हे अल्लाह! तुझे प्रेम मला माझ्या जीवापेक्षा, माझ्या कुटुंबापेक्षा आणि थंड पाण्यापेक्षाही प्रिय कर.", "दाऊद (अ.) यांची दुआ जी नबी ﷺ यांनी सांगितली.", "अल्लाहचे प्रेम ही सर्वात मोठी संपत्ती."),
        "dua_filal_khayrat" to DuaText("सत्कर्मे करणे आणि वाईट सोडणे", "हे अल्लाह! मी तुझ्याकडे सत्कर्मे करणे, वाईट कर्मे सोडणे आणि गरिबांवर प्रेम करण्याची याचना करतो, आणि तू मला क्षमा कर आणि माझ्यावर दया कर. आणि जेव्हा तू एखाद्या समाजाला फितन्यात टाकू इच्छिशील तेव्हा मला फितन्यापासून वाचवून मृत्यू दे. मी तुझ्याकडे तुझे प्रेम, तुझ्यावर प्रेम करणाऱ्यांचे प्रेम आणि तुझ्या प्रेमाजवळ नेणाऱ्या कर्माचे प्रेम मागतो.", "स्वप्नात अल्लाहने नबी ﷺ यांना ही दुआ शिकवली.", "नबी ﷺ म्हणाले: हे सत्य आहे, हे शिका आणि शिकवा."),
        "dua_bi_ilmikal_ghayb" to DuaText("जोपर्यंत जीवन चांगले तोपर्यंत जिवंत ठेव", "हे अल्लाह! तुझ्या अदृश्य ज्ञानाच्या आणि निर्मितीवरील तुझ्या सामर्थ्याच्या आधाराने — जोपर्यंत तुझ्या ज्ञानात जीवन माझ्यासाठी चांगले आहे तोपर्यंत मला जिवंत ठेव, आणि जेव्हा मृत्यू चांगला असेल तेव्हा मृत्यू दे. हे अल्लाह! मी गुप्त आणि उघड दोन्हीत तुझी भीती, आनंदात आणि रागात सत्य बोलणे, आणि गरिबी व श्रीमंतीत संयम मागतो.", "अम्मार बिन यासिर (र.) यांची नमाजची दुआ (प्रारंभिक भाग).", "नबी ﷺ नमाजमध्ये ही दुआ करत."),
        "dua_ism_azam_mannan" to DuaText("इस्म-ए-आजम: अल-मन्नान", "हे अल्लाह! मी तुझ्याकडे याचना करतो या आधाराने की सर्व स्तुती तुझ्यासाठी आहे, तुझ्याशिवाय कोणी उपास्य नाही, तू अत्यंत उपकार करणारा, आकाश व पृथ्वीचा अद्वितीय निर्माता आहेस. हे वैभव आणि सन्मानाच्या मालका, हे सदैव जिवंत, हे आधार!", "नबी ﷺ म्हणाले या व्यक्तीने इस्म-ए-आजमसह दुआ केली.", "या नावाने दुआ केल्यास ती कबूल होते."),
        "dua_ism_azam_ahad_samad" to DuaText("इस्म-ए-आजम: अल-अहद अस-समद", "हे अल्लाह! मी तुझ्याकडे याचना करतो या आधाराने की मी साक्ष देतो तूच अल्लाह आहेस, तुझ्याशिवाय कोणी उपास्य नाही, एकमेव, निरपेक्ष, ज्याने कोणाला जन्म दिला नाही आणि तो जन्मला नाही, आणि त्याच्या तोडीचा कोणी नाही.", "नबी ﷺ म्हणाले याने अल्लाहकडे त्याच्या इस्म-ए-आजमसह मागितले.", "याद्वारे मागितल्यास दिले जाते, आणि दुआ केल्यास कबूल होते."),
        "dua_thabbitni_hadiyan" to DuaText("मला दृढ, मार्गदर्शित आणि मार्गदर्शक बनव", "हे अल्लाह! मला दृढ ठेव आणि मला मार्गदर्शन देणारा आणि मार्गदर्शित बनव.", "नबी ﷺ यांनी जरीर (र.) यांच्यासाठी ही दुआ केली (स्वतःसाठी 'सब्बितनी' म्हणा).", "मूळ दुआ जरीर (र.) यांच्यासाठी 'सब्बित्हु' शब्दांनी आहे."),
        "dua_rabbighfir_tub_alayya" to DuaText("मला क्षमा कर आणि माझी तौबा स्वीकार", "हे माझ्या रब! मला क्षमा कर आणि माझी तौबा स्वीकार, निश्चितच तू तौबा स्वीकारणारा, दयाळू आहेस.", "एका सभेत शंभर वेळा — नबी ﷺ यांची प्रथा.", "सहाबांनी एका सभेत नबी ﷺ यांच्याकडून हे शंभर वेळा मोजून ऐकले."),
        "dua_rafiq_ala" to DuaText("मृत्यूसमीप व्यक्तीची दुआ", "हे अल्लाह! मला क्षमा कर, माझ्यावर दया कर आणि मला सर्वोच्च सोबत्याशी जोड.", "नबी ﷺ यांची शेवटची दुआ — आजारी व्यक्ती स्वतःसाठी.", "नबी ﷺ यांनी निधनाच्या वेळी ही दुआ केली."),
        "dua_la_bas_tahur" to DuaText("आजाऱ्याला दिलासा: पावित्र्य", "काही हरकत नाही, इन शा अल्लाह (हा आजार पापांपासून) पवित्र करणारा आहे.", "आजाऱ्याच्या भेटीत दिलाशासाठी.", "नबी ﷺ आजाऱ्याकडे गेल्यावर हे म्हणत."),
        "dua_talqeen" to DuaText("मृत्यूसमीप व्यक्तीसाठी तलकीन", "अल्लाहशिवाय कोणी उपास्य नाही.", "मृत्यूसमीप व्यक्तीजवळ कलिमा पठण करा (त्याला जबरदस्ती करू नका).", "ज्याचे शेवटचे शब्द 'ला इलाहा इल्लल्लाह' असतील तो जन्नतमध्ये प्रवेश करेल (अबू दाऊद ३११६)."),
        "dua_ahyini_ma_kanat" to DuaText("मृत्यूच्या इच्छेऐवजी", "हे अल्लाह! जोपर्यंत जीवन माझ्यासाठी चांगले आहे तोपर्यंत मला जिवंत ठेव, आणि जेव्हा मृत्यू माझ्यासाठी चांगला असेल तेव्हा मला मृत्यू दे.", "त्रासात मृत्यूची इच्छा करण्याऐवजी.", "नबी ﷺ यांनी मृत्यूची इच्छा करण्यास मनाई करून हे शिकवले."),
        "dua_for_one_i_cursed" to DuaText("ज्याला शब्दांनी दुखावले त्याच्यासाठी", "हे अल्लाह! ज्या मोमिनला मी वाईट बोललो असेन, ते कयामतच्या दिवशी त्याच्यासाठी तुझ्या जवळिकीचे साधन बनव.", "रागात कोणाला वाईट बोलले असल्यास त्याच्यासाठी.", "नबी ﷺ यांची दुआ."),
        "dua_praising_someone" to DuaText("कोणाची स्तुती करताना", "मी अमुकला असे समजतो, आणि अल्लाहच त्याचा हिशोब घेणारा आहे, आणि मी अल्लाहसमोर कोणाच्याही पावित्र्याचा दावा करत नाही.", "कोणाची स्तुती करायची असल्यास अतिशयोक्तीऐवजी.", "नबी ﷺ यांनी स्तुतीचा हा शिष्टाचार शिकवला."),
        "dua_being_praised" to DuaText("जेव्हा तुमची स्तुती होते", "हे अल्लाह! ते जे म्हणत आहेत त्याबद्दल मला पकडू नकोस, आणि माझी ती पापे माफ कर जी त्यांना माहीत नाहीत.", "स्वतःची स्तुती ऐकून — एका सहाबी (र.) यांची प्रथा.", "स्तुतीवर अहंकारापासून वाचण्याचा मार्ग."),
        "dua_non_muslim_sneezes" to DuaText("गैर-मुस्लिम शिंकल्यास", "अल्लाह तुला मार्गदर्शन देवो आणि तुझी स्थिती सुधारो.", "गैर-मुस्लिम शिंकून 'अल्हम्दुलिल्लाह' म्हणाल्यास.", "यहूदी नबी ﷺ यांच्याजवळ शिंकत की त्यांनी 'यरहमुकल्लाह' म्हणावे, तेव्हा ते हे म्हणत."),
        "dua_reply_ahl_kitab_salam" to DuaText("अहले किताबच्या सलामला उत्तर", "आणि तुमच्यावरही.", "अहले किताबने सलाम केल्यास.", "नबी ﷺ यांचा आदेश."),
        "dua_fasting_invited" to DuaText("रोजात आमंत्रण मिळाल्यास", "मी रोजात आहे.", "रोजा असताना आमंत्रण मिळाल्यास किंवा कोणी भांडण केल्यास.", "रोजेदाराने आमंत्रण स्वीकारल्यास यजमानासाठी दुआ करावी."),
        "dua_for_who_gave_drink" to DuaText("ज्याने खाऊ-पाजले त्याच्यासाठी", "हे अल्लाह! ज्याने मला खाऊ घातले त्याला खाऊ घाल, आणि ज्याने मला पाजले त्याला पाज.", "जो खाऊ-पाजतो त्याच्यासाठी.", "नबी ﷺ यांनी मिकदाद (र.) यांच्यासाठी ही दुआ केली."),
        "dua_eid_greeting" to DuaText("ईदच्या शुभेच्छा", "अल्लाह आमच्याकडून आणि तुमच्याकडून (कर्मे) स्वीकारो.", "ईदच्या दिवशी एकमेकांना — सहाबा (र.) यांची प्रथा.", "सहाबा ईदला भेटल्यावर हे म्हणत."),
        "dua_wedding_night" to DuaText("निकाहनंतर नववधूसाठी", "हे अल्लाह! मी तुझ्याकडे तिचे भले आणि ज्या स्वभावावर तू तिला निर्माण केलेस त्याचे भले मागतो, आणि तिच्या वाईटापासून आणि त्या स्वभावाच्या वाईटापासून तुझा आश्रय मागतो.", "निकाहनंतर पत्नीच्या कपाळावर हात ठेवून.", "नबी ﷺ यांची शिकवण — निकाहमध्ये बरकत."),
        "dua_istisqa_ibadak" to DuaText("तुझ्या दासांना आणि प्राण्यांना पाणी दे", "हे अल्लाह! तुझ्या दासांना आणि प्राण्यांना पाणी दे, तुझी कृपा पसरव आणि तुझ्या मृत भूमीला जिवंत कर.", "पावसाची मागणी (इस्तिस्का).", "नबी ﷺ पावसासाठी ही दुआ करत."),
        "dua_seeing_clouds" to DuaText("काळे ढग पाहून", "हे अल्लाह! मी याच्या वाईटापासून तुझा आश्रय मागतो.", "आकाशात ढग पाहून; पाऊस पडल्यास 'अल्लाहुम्मा सय्यिबन नाफिआ'.", "नबी ﷺ ढग पाहून काम सोडत आणि ही दुआ करत."),
        "dua_jamarat" to DuaText("जमरातवर खडे मारणे", "अल्लाह सर्वात महान आहे.", "प्रत्येक खडा मारताना.", "नबी ﷺ प्रत्येक खड्यासोबत तकबीर म्हणत, मग पहिल्या आणि दुसऱ्या जमरानंतर किब्लाकडे तोंड करून दीर्घ दुआ करत."),
        "dua_rabbi_ainni" to DuaText("हे माझ्या रब, मला मदत कर, माझ्याविरुद्ध नाही", "हे माझ्या रब! मला मदत कर आणि माझ्याविरुद्ध मदत करू नकोस, मला विजय दे आणि माझ्यावर विजय देऊ नकोस, माझ्या बाजूने योजना कर आणि माझ्याविरुद्ध योजना करू नकोस, मला मार्गदर्शन दे आणि मार्गदर्शन माझ्यासाठी सोपे कर, आणि जो माझ्यावर अन्याय करतो त्याच्याविरुद्ध मला मदत कर.", "नबी ﷺ यांची व्यापक दुआ (प्रारंभिक भाग).", "दुनिया आणि दीनची प्रत्येक मदत एकत्र करणारी दुआ."),
        "dua_ati_nafsi_taqwaha" to DuaText("माझ्या मनाला त्याचा तक्वा दे", "हे अल्लाह! माझ्या मनाला त्याचा तक्वा दे आणि त्याला पवित्र कर, तूच त्याला सर्वोत्तम पवित्र करणारा आहेस, तूच त्याचा संरक्षक आणि मालक आहेस.", "मनाच्या सुधारणेसाठी आणि शुद्धीकरणासाठी.", "नबी ﷺ ही दुआ करत."),
        "dua_iqsim_lana_khashyatik" to DuaText("आम्हाला तुझी अशी भीती दे", "हे अल्लाह! आम्हाला तुझी इतकी भीती दे जी आमच्या आणि तुझ्या अवज्ञेमध्ये आड येईल, इतके आज्ञापालन जे आम्हाला तुझ्या जन्नतपर्यंत पोहोचवेल, आणि इतका विश्वास ज्याने दुनियेची संकटे आमच्यासाठी सोपी होतील. जोपर्यंत आम्हाला जिवंत ठेवशील तोपर्यंत आमच्या कानांचा, डोळ्यांचा आणि शक्तीचा आम्हाला लाभ दे आणि ते आमचे वारस बनव. जो आमच्यावर अन्याय करतो त्याच्याकडून आमचा बदला घे, शत्रूंविरुद्ध आम्हाला मदत कर, आमचे संकट आमच्या दीनमध्ये टाकू नकोस, दुनियेला आमची सर्वात मोठी चिंता आणि आमच्या ज्ञानाची मर्यादा बनवू नकोस, आणि आमच्यावर अशा व्यक्तीला लादू नकोस जो आमच्यावर दया करणार नाही.", "सभेतून उठताना — नबी ﷺ क्वचितच ही दुआ न करता उठत.", "दीन, दुनिया आणि आखिरतच्या भल्याची व्यापक दुआ."),
        "dua_infani_bima_allamtani" to DuaText("जे शिकवलेस त्याचा लाभ दे", "हे अल्लाह! तू मला जे शिकवलेस त्याचा मला लाभ दे, मला ते शिकव जे मला लाभदायक आहे, आणि माझ्या ज्ञानात वाढ कर.", "ज्ञान मिळवताना किंवा अभ्यासापूर्वी.", "उपयुक्त ज्ञान आणि त्यावर आचरणाची दुआ."),
        "dua_jar_su" to DuaText("वाईट शेजाऱ्यापासून आश्रय", "हे अल्लाह! मी कायमच्या निवासस्थानाच्या वाईट शेजाऱ्यापासून तुझा आश्रय मागतो, कारण प्रवासातील शेजारी तर बदलतो.", "वाईट शेजाऱ्यापासून संरक्षणासाठी.", "नबी ﷺ यांनी यापासून आश्रय मागण्याचा आदेश दिला."),
        "dua_ishfi_abdak" to DuaText("आजाऱ्याच्या आरोग्यासाठी", "हे अल्लाह! तुझ्या दासाला बरे कर जेणेकरून तो तुझ्यासाठी शत्रूचा सामना करेल किंवा तुझ्यासाठी नमाजकडे चालत जाईल.", "आजाऱ्याच्या भेटीत त्याच्यासाठी.", "नबी ﷺ यांनी आजाऱ्यासाठी हे म्हणायला शिकवले."),
        "dua_la_mania" to DuaText("तू जे देतोस ते कोणी रोखू शकत नाही", "अल्लाहशिवाय कोणी उपास्य नाही, तो एकटा आहे, त्याला कोणी भागीदार नाही, राज्य आणि स्तुती त्याचीच आणि तो प्रत्येक गोष्टीवर समर्थ आहे. हे अल्लाह! तू जे देतोस ते कोणी रोखू शकत नाही आणि तू जे रोखतोस ते कोणी देऊ शकत नाही, आणि कोणत्याही श्रीमंताची श्रीमंती तुझ्यासमोर उपयोगी पडत नाही.", "फर्ज नमाजच्या सलामनंतर.", "नबी ﷺ प्रत्येक फर्ज नमाजनंतर हे म्हणत."),
        "dua_slaughtering" to DuaText("प्राणी जिबह करताना", "अल्लाहच्या नावाने, आणि अल्लाह सर्वात महान आहे.", "कुर्बानी किंवा जिबह करताना.", "नबी ﷺ यांनी कुर्बानीच्या वेळी बिस्मिल्लाह आणि तकबीर म्हटली."),
        "dua_undressing" to DuaText("कपडे काढताना", "अल्लाहच्या नावाने.", "कपडे काढताना (आंघोळ किंवा कपडे बदलताना).", "जिन्नांची नजर आणि माणसाच्या गुप्तांगांमध्ये पडदा बनते."),
        "dua_ilbas_jadidan" to DuaText("कोणाला नवीन कपड्यांत पाहून", "नवीन घाला, प्रशंसनीय जीवन जगा आणि शहीद होऊन मरा.", "एखाद्या मुस्लिम बंधूला नवीन कपड्यांत पाहून.", "नबी ﷺ यांनी उमर (र.) यांना नवीन कपड्यांत पाहून ही दुआ दिली."),
        "dua_hajj_la_riya" to DuaText("दिखाव्यापासून मुक्त हज", "हे अल्लाह! असा हज ज्यात ना दिखावा असेल ना प्रसिद्धीची इच्छा.", "हजच्या नियतीच्या वेळी प्रामाणिकपणासाठी.", "नबी ﷺ यांनी हजच्या वेळी ही दुआ केली."),
        "dua_q_muslimayni_laka" to DuaText("आम्हाला आज्ञाधारक बनव (इब्राहीम व इस्माईल अ.)", "हे आमच्या रब! आम्हा दोघांना तुझे आज्ञाधारक बनव आणि आमच्या संततीतूनही एक समुदाय तुझा आज्ञाधारक बनव, आम्हाला आमच्या उपासनेच्या पद्धती दाखव आणि आमची तौबा स्वीकार, निश्चितच तूच तौबा स्वीकारणारा, दयाळू आहेस.", "स्वतःसाठी आणि संततीसाठी आज्ञाधारकतेची दुआ.", "काबा बांधतानाची दुआ."),
        "dua_q_iftah_baynana" to DuaText("आमच्यात निर्णय कर (शुऐब अ.)", "हे आमच्या रब! आमच्यात आणि आमच्या लोकांमध्ये सत्याने निर्णय कर, आणि तू सर्वोत्तम निर्णय करणारा आहेस.", "सत्य आणि असत्यामधील निर्णयासाठी.", "लोकांनी नाकारल्यावर शुऐब (अ.) यांची दुआ."),
        "dua_q_la_akuna_zahiran" to DuaText("कधीही गुन्हेगारांचा मदतगार नाही (मूसा अ.)", "हे माझ्या रब! तू माझ्यावर जी कृपा केलीस त्यामुळे मी कधीही गुन्हेगारांचा मदतगार होणार नाही.", "अल्लाहच्या कृपेचे आभार आणि पाप्यांना मदत न करण्याचे वचन.", "तौबानंतर मूसा (अ.) यांचे वचन."),
        "dua_q_nuh_unsurni" to DuaText("मला मदत कर, त्यांनी मला खोटे ठरवले (नूह अ.)", "हे माझ्या रब! मला मदत कर कारण त्यांनी मला खोटे ठरवले.", "जेव्हा लोक खोटे ठरवतात आणि सत्य मानत नाहीत.", "नूह (अ.) यांची दुआ जी कबूल झाली."),
        "dua_q_ihkum_bil_haqq" to DuaText("हे माझ्या रब, सत्याने निर्णय कर", "हे माझ्या रब! सत्याने निर्णय कर. आणि आमचा रब परम दयाळू आहे, ज्याच्याकडे तुम्ही रचलेल्या गोष्टींविरुद्ध मदत मागितली जाते.", "खोट्या गोष्टी आणि आरोपांच्या विरोधात.", "नबी ﷺ यांना शिकवलेली दुआ."),
        "dua_ghalabatid_dayn" to DuaText("जड कर्ज आणि शत्रूंपासून आश्रय", "हे अल्लाह! मी कर्जाच्या दबावापासून, शत्रूच्या वर्चस्वापासून आणि शत्रूंच्या आनंदापासून तुझा आश्रय मागतो.", "कर्जाचा भार आणि शत्रूंच्या वर्चस्वापासून संरक्षण.", "नबी ﷺ या गोष्टींपासून आश्रय मागत."),
        "dua_faqr_qillah_dhillah" to DuaText("दारिद्र्य आणि अपमानापासून आश्रय", "हे अल्लाह! मी दारिद्र्य, कमतरता आणि अपमानापासून तुझा आश्रय मागतो, आणि अन्याय करण्यापासून किंवा माझ्यावर अन्याय होण्यापासून.", "तंगी, कमतरता आणि अपमानापासून वाचण्यासाठी.", "नबी ﷺ यांनी शिकवलेला आश्रय."),
        "dua_five_things_new_muslim" to DuaText("क्षमा, दया, मार्गदर्शन, आरोग्य, रोजी", "हे अल्लाह! मला क्षमा कर, माझ्यावर दया कर, मला मार्गदर्शन दे, मला सुरक्षितता दे आणि मला रोजी दे.", "नबी ﷺ नवीन मुस्लिमाला नमाजसोबत ही दुआ शिकवत.", "नबी ﷺ म्हणाले: हे शब्द तुझ्यासाठी दुनिया आणि आखिरत एकत्र करतात."),
        "dua_ruku_laka_raka_tu" to DuaText("रुकूमध्ये — तुझ्यासाठी रुकू केला", "हे अल्लाह! मी तुझ्यासाठी रुकू केला, तुझ्यावर ईमान आणले आणि तुला शरण गेलो. माझे कान, डोळे, मेंदू, हाडे आणि स्नायू तुझ्यासमोर नम्र झाले.", "रुकूमध्ये (विशेषतः नफ्ल नमाजमध्ये).", "नबी ﷺ रुकूमध्ये हे पठण करत."),
        "dua_sujood_laka_sajadtu" to DuaText("सजद्यात — तुला सजदा केला", "हे अल्लाह! मी तुला सजदा केला, तुझ्यावर ईमान आणले आणि तुला शरण गेलो. माझा चेहरा त्याच्यासमोर सजद्यात आहे ज्याने त्याला निर्माण केले, त्याला आकार दिला आणि त्याचे कान व डोळे उघडले. बरकतवान आहे अल्लाह, सर्वोत्तम निर्माता.", "सजद्यात (विशेषतः नफ्ल नमाजमध्ये).", "नबी ﷺ सजद्यात हे पठण करत."),
        "dua_ruku_sujood_subhanaka" to DuaText("हे आमच्या रब, तू पवित्र आहेस — मला क्षमा कर", "हे अल्लाह, आमच्या रब! तू पवित्र आहेस तुझ्या स्तुतीसह. हे अल्लाह! मला क्षमा कर.", "रुकू आणि सजद्यात.", "आयशा (र.): नबी ﷺ रुकू आणि सजद्यात वारंवार हे पठण करत."),
        "dua_q_musa_li_akhi" to DuaText("मला आणि माझ्या भावाला क्षमा कर (मूसा अ.)", "हे माझ्या रब! मला आणि माझ्या भावाला क्षमा कर आणि आम्हाला तुझ्या कृपेत प्रवेश दे, आणि तू सर्व दयाळूंपेक्षा अधिक दयाळू आहेस.", "स्वतःसाठी आणि भाऊ/प्रियजनांसाठी क्षमा.", "हारून (अ.) यांच्यासाठी मूसा (अ.) यांची दुआ."),
        "dua_q_ufawwidu_amri" to DuaText("मी माझे काम अल्लाहच्या स्वाधीन करतो", "आणि मी माझे काम अल्लाहच्या स्वाधीन करतो, निश्चितच अल्लाह दासांना पूर्णपणे पाहणारा आहे.", "जेव्हा लोक विरोध करतात आणि प्रकरण अल्लाहच्या स्वाधीन करायचे असते.", "फिरऔनच्या लोकांतील मोमिनचे वचन; त्यानंतर अल्लाहने त्याला त्यांच्या कटांपासून वाचवले."),
        "dua_q_hawariyyun" to DuaText("हवारींची दुआ — आम्हाला साक्षीदारांत लिही", "हे आमच्या रब! तू जे उतरवलेस त्यावर आम्ही ईमान आणले आणि आम्ही रसूलचे अनुसरण केले, म्हणून आम्हाला साक्ष देणाऱ्यांत लिही.", "ईमान आणि रसूलच्या अनुसरणावर दृढतेसाठी.", "ईसा (अ.) यांच्या हवारींची दुआ."),
        "dua_q_la_tukhzini" to DuaText("मला अपमानित करू नकोस (इब्राहीम अ.)", "आणि ज्या दिवशी लोकांना उठवले जाईल त्या दिवशी मला अपमानित करू नकोस.", "कयामतच्या अपमानापासून वाचण्यासाठी.", "आखिरतसाठी इब्राहीम (अ.) यांची दुआ."),
        "dua_iftar_laka_sumtu" to DuaText("इफ्तार — तुझ्यासाठी रोजा ठेवला", "हे अल्लाह! मी तुझ्यासाठी रोजा ठेवला आणि तुझ्याच रोजीने इफ्तार केला.", "रोजा सोडताना (इफ्तारची प्रसिद्ध दुआ).", "नबी ﷺ इफ्तारच्या वेळी हे म्हणत. ही मुरसल रिवायत आहे जिला इतर रिवायतींनी बळकटी मिळते; हनफी आणि बहुसंख्यांमध्ये इफ्तारला हिचे पठण प्रचलित आहे."),
        "dua_iftar_ibn_umar" to DuaText("इफ्तार — तुझ्या विशाल कृपेने मला क्षमा कर", "हे अल्लाह! मी तुझ्या त्या कृपेच्या आधाराने जी प्रत्येक गोष्टीला व्यापून आहे, तुझ्याकडे याचना करतो की मला क्षमा कर.", "इफ्तारच्या वेळी — अब्दुल्लाह बिन अम्र (र.) ही दुआ करत; इफ्तारला रोजेदाराची दुआ नाकारली जात नाही.", "हदीस: इफ्तारच्या वेळी रोजेदाराची दुआ नाकारली जात नाही."),
        "dua_inni_saim" to DuaText("रोजात कोणी चिथावल्यास", "मी रोजात आहे, मी रोजात आहे.", "रोजा असताना कोणी शिवी दिल्यास किंवा भांडण केल्यास.", "नबी ﷺ म्हणाले: रोजा ढाल आहे, म्हणून रोजेदाराने अश्लील बोलू नये ना मूर्खपणा करावा — कोणी भांडल्यास दोनदा हे म्हणावे."),
        "dua_eid_takbeer" to DuaText("ईदगाहला जाताना तकबीर", "अल्लाह सर्वात महान आहे, अल्लाह सर्वात महान आहे, अल्लाहशिवाय कोणी उपास्य नाही, आणि अल्लाह सर्वात महान आहे, अल्लाह सर्वात महान आहे, आणि सर्व स्तुती अल्लाहसाठीच आहे.", "चांदरातपासून ईदुल फित्रच्या नमाजपर्यंत, विशेषतः ईदगाहला जाताना.", "कुरआनचा आदेश: 'जेणेकरून तुम्ही गणना पूर्ण करा आणि अल्लाहची महानता सांगा' (अल-बकरा २:१८५). इब्न मसऊद (र.) हीच तकबीर म्हणत."),
        "dua_ahsin_aqibatana" to DuaText("प्रत्येक कामात आमचा शेवट चांगला कर", "हे अल्लाह! सर्व कामांत आमचा शेवट चांगला कर, आणि आम्हाला दुनियेच्या अपमानापासून आणि आखिरतच्या शिक्षेपासून वाचव.", "प्रत्येक कामाच्या चांगल्या परिणामासाठी.", "जो ही दुआ करतो आणि परीक्षेपूर्वी मरण पावतो तो (फितन्यापासून सुरक्षित) मरतो."),
        "dua_fadlika_wa_rahmatik" to DuaText("तुझी कृपा आणि दया मागतो", "हे अल्लाह! मी तुझ्याकडे तुझी कृपा आणि तुझी दया मागतो, कारण यांचा मालक तुझ्याशिवाय कोणी नाही.", "रोजी आणि कृपा मागताना.", "नबी ﷺ यांच्याकडे पाहुणे आले आणि जेवण नव्हते तेव्हा त्यांनी ही दुआ केली, मग भेट आली."),
        "dua_allahu_akbar_kabira_2696" to DuaText("एका ग्रामीणाला शिकवलेले शब्द", "अल्लाहशिवाय कोणी उपास्य नाही, तो एकटा आहे, त्याला कोणी भागीदार नाही. अल्लाह अत्यंत महान आहे, अल्लाहसाठी विपुल स्तुती आहे, सर्व जगांचा रब अल्लाह पवित्र आहे, आणि प्रबळ, शहाण्या अल्लाहशिवाय कोणतीही शक्ती व सामर्थ्य नाही.", "जिक्र आणि दुआचे व्यापक वाक्य — एका ग्रामीणाला शिकवले.", "यानंतर 'अल्लाहुम्मग्फिर ली वरहम्नी वहदिनी वरजुक्नी' म्हणायला शिकवले."),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("पुढची-मागची पापे क्षमा कर", "हे अल्लाह! माझी ती पापे क्षमा कर जी मी आधी केली आणि नंतर केली, लपून केली आणि उघडपणे केली, जो अतिरेक केला, आणि जी तू माझ्यापेक्षा जास्त जाणतोस. तूच पुढे करणारा आणि तूच मागे करणारा आहेस, तुझ्याशिवाय कोणी उपास्य नाही.", "तशह्हुद आणि दुरूदनंतर सलामपूर्वी.", "नबी ﷺ नमाजच्या शेवटी तशह्हुद आणि सलामदरम्यान हे पठण करत."),
        "dua_jiddi_wa_hazli" to DuaText("गांभीर्य आणि थट्टेतील पापे क्षमा कर", "हे अल्लाह! माझी ती पापे क्षमा कर जी गांभीर्याने आणि थट्टेत झाली, चुकून आणि जाणूनबुजून झाली — आणि हे सर्व माझ्यात आहे.", "जाणता-अजाणता सर्व प्रकारच्या पापांची क्षमा.", "नबी ﷺ यांचा व्यापक इस्तिगफार."),
        "dua_rising_ruku_mil" to DuaText("रुकूनंतर — आकाशभर स्तुती", "हे आमच्या रब! तुझ्यासाठीच सर्व स्तुती आहे, आकाशभर, पृथ्वीभर, आणि त्यानंतर तू जे इच्छिशील तेवढी.", "रुकूतून उठून 'रब्बना लकल हम्द' सोबत.", "नबी ﷺ रुकूतून उठून हे म्हणत."),
        "dua_istiftah_kabira" to DuaText("अल्लाह महान, विपुल स्तुती", "अल्लाह अत्यंत महान आहे, अल्लाहसाठी विपुल स्तुती आहे, आणि सकाळ-संध्याकाळ अल्लाहची पवित्रता.", "नमाज सुरू करताना (सनाचे एक रूप).", "नबी ﷺ म्हणाले: यासाठी आकाशाचे दरवाजे उघडले गेले."),
        "dua_q_ashku_bathhi" to DuaText("मी फक्त अल्लाहकडे तक्रार करतो (याकूब अ.)", "मी माझे दुःख आणि वेदना यांची तक्रार फक्त अल्लाहकडे करतो.", "खोल दुःख आणि वियोगाच्या वेळी.", "याकूब (अ.) यांनी यूसुफ (अ.) यांच्या वियोगात हे म्हटले."),
        "dua_q_khayrun_hafiza" to DuaText("अल्लाह सर्वोत्तम रक्षक आहे", "अल्लाहच सर्वोत्तम रक्षक आहे, आणि तो सर्व दयाळूंपेक्षा अधिक दयाळू आहे.", "मुलांना किंवा प्रियजनांना प्रवासाला पाठवताना.", "याकूब (अ.) यांनी आपल्या मुलाला अल्लाहच्या स्वाधीन करताना हे म्हटले."),
        "dua_q_aqraba_rashada" to DuaText("माझा रब मला भल्याच्या जवळचा मार्ग दाखवेल", "आशा आहे की माझा रब मला यापेक्षाही भल्याच्या जवळचा मार्ग दाखवेल.", "एखाद्या कामात चांगला मार्ग शोधताना.", "विसरल्यावर हे म्हणण्याचे नबी ﷺ यांना शिकवले गेले."),
        "dua_q_sawa_as_sabil" to DuaText("मला सरळ मार्ग दाखव (मूसा अ.)", "आशा आहे की माझा रब मला सरळ मार्ग दाखवेल.", "नव्या प्रवासाला किंवा अनोळखी मार्गावर जाताना.", "मदयनकडे वळताना मूसा (अ.) यांनी हे म्हटले."),
        "dua_q_not_among_wrongdoers" to DuaText("मला अत्याचाऱ्यांत सामील करू नकोस", "हे माझ्या रब! मला अत्याचारी लोकांत सामील करू नकोस.", "अत्याचाऱ्यांपासून वेगळे ठेवण्यासाठी अल्लाहकडे दुआ."),
        "dua_q_do_not_make_us_trial" to DuaText("आम्हाला परीक्षा बनवू नकोस", "हे आमच्या रब! आम्हाला काफिरांसाठी परीक्षा बनवू नकोस आणि आम्हाला क्षमा कर, हे आमच्या रब! निश्चितच तू प्रबळ, शहाणा आहेस.", "इब्राहीम (अ.) आणि त्यांच्या साथीदारांची दुआ."),
        "dua_morning_witness" to DuaText("सकाळी तौहीदची साक्ष", "हे अल्लाह! मी सकाळ केली, मी तुला, तुझ्या अर्श उचलणाऱ्यांना, तुझ्या फरिश्त्यांना आणि तुझ्या सर्व निर्मितीला साक्षी ठेवतो की तूच अल्लाह आहेस, तुझ्याशिवाय कोणी उपास्य नाही, तू एकटा आहेस, तुला कोणी भागीदार नाही, आणि मुहम्मद ﷺ तुझे दास आणि रसूल आहेत.", "रिवायतीत सकाळी चार वेळा पठणाचा उल्लेख आहे."),
        "dua_evening_witness" to DuaText("संध्याकाळी तौहीदची साक्ष", "हे अल्लाह! मी संध्याकाळ केली, मी तुला, तुझ्या अर्श उचलणाऱ्यांना, तुझ्या फरिश्त्यांना आणि तुझ्या सर्व निर्मितीला साक्षी ठेवतो की तूच अल्लाह आहेस, तुझ्याशिवाय कोणी उपास्य नाही, तू एकटा आहेस, तुला कोणी भागीदार नाही, आणि मुहम्मद ﷺ तुझे दास आणि रसूल आहेत.", "रिवायतीत संध्याकाळी चार वेळा पठणाचा उल्लेख आहे."),
        "dua_morning_blessing" to DuaText("सकाळी कृपांचे आभार", "हे अल्लाह! सकाळी मला किंवा तुझ्या कोणत्याही निर्मितीला जी कृपा मिळाली ती फक्त तुझ्याकडूनच आहे, तुला कोणी भागीदार नाही; म्हणून सर्व स्तुती आणि आभार तुझेच आहेत.", "सकाळी अल्लाहच्या कृपांबद्दल आभाराचा जिक्र."),
        "dua_evening_blessing" to DuaText("संध्याकाळी कृपांचे आभार", "हे अल्लाह! संध्याकाळी मला किंवा तुझ्या कोणत्याही निर्मितीला जी कृपा मिळाली ती फक्त तुझ्याकडूनच आहे, तुला कोणी भागीदार नाही; म्हणून सर्व स्तुती आणि आभार तुझेच आहेत.", "संध्याकाळी अल्लाहच्या कृपांबद्दल आभाराचा जिक्र."),
    )
}
